CREATE OR REPLACE FUNCTION public.ticare_action_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'Cannot change action plan ownership or creation date';
    END IF;
  END IF;
  NEW.updated_at=now();
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.ticare_protect_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL AND (
    NEW.id IS DISTINCT FROM OLD.id OR
    NEW.role IS DISTINCT FROM OLD.role OR
    NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Only display_name can be changed';
  END IF;
  RETURN NEW;
END;
$function$
